// Contrato: recibe un precio en centavos y un porcentaje (0-100); devuelve centavos enteros.
function applyDiscount(priceInCents, percent) {
  if (!Number.isInteger(priceInCents) || priceInCents < 0) {
    throw new RangeError("priceInCents debe ser un entero no negativo");
  }
  if (percent < 0 || percent > 100) {
    throw new RangeError("percent debe estar entre 0 y 100");
  }
  return Math.round(priceInCents * (1 - percent / 100));
}

