function linearSearch(sorted, target) {
  for (let i = 0; i < sorted.length; i++) if (sorted[i] === target) return i; // O(n)
  return -1;
}

function binarySearch(sorted, target) {
  let low = 0, high = sorted.length - 1;
  while (low <= high) {                       // cada vuelta descarta la mitad: O(log n)
    const mid = Math.floor((low + high) / 2);
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) low = mid + 1; else high = mid - 1;
  }
  return -1;
}

const data = Array.from({ length: 1000 }, (_, i) => i * 2);
