// 1) Fuerza bruta: O(n²) tiempo, O(1) memoria
function hasDuplicatesBrute(list) {
  for (let i = 0; i < list.length; i++)
    for (let j = i + 1; j < list.length; j++)
      if (list[i] === list[j]) return true;
  return false;
}

// 2) Ordenar y comparar vecinos: O(n log n) tiempo, O(n) memoria por la copia
function hasDuplicatesSort(list) {
  const copy = [...list].sort((a, b) => a - b);
  for (let i = 1; i < copy.length; i++) if (copy[i] === copy[i - 1]) return true;
  return false;
}

// 3) Set: O(n) tiempo, O(n) memoria
function hasDuplicatesSet(list) {
  return new Set(list).size !== list.length;
}

