class ValidationError extends Error {
  constructor(field, message, options) {
    super(message, options);
    this.name = "ValidationError";
    this.field = field;
  }
}

function parseAge(input) {
  const age = Number(input);
  if (!Number.isInteger(age) || age < 0) {
    throw new ValidationError("age", `Edad inválida: ${JSON.stringify(input)}`);
  }
  return age;
}

function loadProfile(raw) {
  try {
    return { age: parseAge(raw.age) };
  } catch (error) {
    if (error instanceof ValidationError) {
      throw new Error(`Perfil rechazado (campo ${error.field})`, { cause: error });
    }
    throw error;                      // lo inesperado se propaga sin ocultarlo
  } finally {
    // aquí se liberarían recursos abiertos, haya o no error
  }
}

