const ok = (v, ms) => new Promise((r) => setTimeout(() => r(v), ms));
const fail = (msg, ms) => new Promise((_, rej) => setTimeout(() => rej(new Error(msg)), ms));

async function main() {
  // all: se rechaza en cuanto una falla
  try {
    await Promise.all([ok("A", 10), fail("B falló", 20), ok("C", 30)]);
  } catch (e) {
    console.log("all:", e.message);                           // all: B falló
  }

  // allSettled: informa de cada tarea
  const results = await Promise.allSettled([ok("A", 10), fail("B falló", 20), ok("C", 30)]);
  console.log(results.map((r) => r.status));                // [ 'fulfilled', 'rejected', 'fulfilled' ]

  // race: tiempo límite
  const timeout = (ms) => new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), ms));
  try {
    await Promise.race([ok("lento", 200), timeout(50)]);
  } catch (e) {
    console.log("race:", e.message);                          // race: timeout
  }

  // any: primera con éxito
  console.log("any:", await Promise.any([fail("x", 10), ok("réplica", 30)])); // any: réplica
}
main();

