// Mal modelo: permite combinaciones imposibles (loading con error y datos a la vez)
type BadState = { loading: boolean; data?: string[]; error?: string };

// Buen modelo: cada estado lleva solo lo que le corresponde
type RequestState =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "success"; data: string[] }
  | { status: "error"; message: string };

function render(state: RequestState): string {
  switch (state.status) {
    case "idle": return "Esperando";
    case "loading": return "Cargando…";
    case "success": return `${state.data.length} resultados`;
    case "error": return `Error: ${state.message}`;
  }
}

