// 1) Tipos primero: el vocabulario del dominio
type Cents = number & { readonly __brand: "Cents" };      // «tipo marcado»: un número que son centavos
const cents = (n: number): Cents => {
  if (!Number.isInteger(n) || n < 0) throw new RangeError("Cents debe ser un entero no negativo");
  return n as Cents;
};

type Plan = "basic" | "pro";
type Customer = { readonly id: string; plan: Plan; seats: number };

type QuoteError =
  | { code: "INVALID_SEATS"; seats: number }
  | { code: "UNKNOWN_PLAN"; plan: string };

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

// 2) El contrato en la firma: recibe un cliente, devuelve un resultado o un error tipado
const PRICE_PER_SEAT: Record<Plan, Cents> = { basic: cents(900), pro: cents(2500) };

function quote(customer: Customer): Result<Cents, QuoteError> {
  if (!Number.isInteger(customer.seats) || customer.seats < 1) {
    return { ok: false, error: { code: "INVALID_SEATS", seats: customer.seats } };
  }
  const unit = PRICE_PER_SEAT[customer.plan];
  return { ok: true, value: cents(unit * customer.seats) };
}

// 3) Quien llama está obligado a tratar el fallo
const result = quote({ id: "c1", plan: "pro", seats: 3 });
if (result.ok) console.log("Total (centavos):", result.value);   // 7500
else console.log("Error:", result.error.code);

const bad = quote({ id: "c2", plan: "basic", seats: 0 });
console.log(bad.ok ? "ok" : bad.error.code);                      // INVALID_SEATS
